//! 🧪️ Neutral curves, world transforms, original finite stock and private publication.
use super::*;
use serde_json::{Value,json};
use std::collections::BTreeSet;
use semio_framework_value::{work::RetainedWorkLedger,RetainedCloneGrant};
#[path="../../../🛤️path/🎟️work/🧪️tests/🦀️.rs"]
mod funding;
funding::physical_close!(PathBooleanRetirement,funding::PhysicalClose);
fn funded(input:PathBooleanInput)->funding::Funded<PathBooleanJob>{funding::Funded::new(PathBooleanJob::new(input),include_str!("🎟️work/🔣️.json"))}
fn step(job:&mut funding::Funded<PathBooleanJob>,items:usize)->Result<PathBooleanProgress,BooleanError>{job.turn(items,|job,work|job.advance(items,work))}
fn drain(retired:&mut funding::Funded<PathBooleanRetirement>,items:usize)->u64{let mut turns=0;while !retired.terminal_is_empty(){retired.close_turn(items).unwrap();turns+=1;assert!(turns<retired.turn_bound());}turns}
fn rows()->Vec<Value>{serde_json::from_str::<Value>(include_str!("🧫️fixtures/🔣️.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn point(v:&Value)->Vec2{[v[0].as_f64().unwrap(),v[1].as_f64().unwrap()]}
fn segment(v:&Value)->PathSegment{match v["kind"].as_str().unwrap(){
 "move"=>PathSegment::Move{to:point(&v["to"])},"line"=>PathSegment::Line{to:point(&v["to"])},"quad"=>PathSegment::Quad{ctrl:point(&v["ctrl"]),to:point(&v["to"])},
 "cubic"=>PathSegment::Cubic{ctrl1:point(&v["ctrl1"]),ctrl2:point(&v["ctrl2"]),to:point(&v["to"])},
 "arc"=>PathSegment::Arc{rx:v["rx"].as_f64().unwrap(),ry:v["ry"].as_f64().unwrap(),rotation:v["rotation"].as_f64().unwrap(),large_arc:v["largeArc"].as_bool().unwrap(),sweep:v["sweep"].as_bool().unwrap(),to:point(&v["to"])},
 "close"=>PathSegment::Close,_=>panic!("Unknown fixture segment")}}
fn input(row:&Value)->PathBooleanInput{PathBooleanInput{operation:BooleanOperation::parse(row["operation"].as_str().unwrap()).unwrap(),operands:row["operands"].as_array().unwrap().iter().map(|v|PathBooleanOperand{
 segments:v["segments"].as_array().unwrap().iter().map(segment).collect(),transform:std::array::from_fn(|at|v["transform"][at].as_f64().unwrap()),tolerance:v["tolerance"].as_f64().unwrap(),fill_rule:if v["fillRule"]=="evenodd"{BooleanFillRule::Evenodd}else{BooleanFillRule::Nonzero}}).collect(),epsilon:1e-8,max_edges:65536,max_parameters:262144,max_atomic_edges:65536,max_segments:65536,max_work:10000000}}
fn finish(value:PathBooleanInput,grant:usize)->(funding::Funded<Vec<PathSegment>>,PathBooleanProgress){let mut job=funded(value);assert_eq!(job.result().unwrap_err(),BooleanError::Incomplete);let mut work=0;for _ in 0..job.turn_bound(){let p=step(&mut job,grant).unwrap();assert!(p.work>=work&&p.work-work<=grant as u64);assert!(p.done||job.last_turn_work()>0);work=p.work;if p.done{let(mut close,output)=job.retire_with(PathBooleanJob::into_retirement);drain(&mut close,grant);let wallet=close.finish_closed();return(funding::Funded::from_parts(output.unwrap(),wallet),p);}assert_eq!(job.result().unwrap_err(),BooleanError::Incomplete);}panic!("Finite path observation bound exhausted");}
fn close(job:funding::Funded<PathBooleanJob>)->funding::Wallet{let(mut retired,output)=job.retire_with(PathBooleanJob::into_retirement);drain(&mut retired,1);let mut wallet=retired.finish_closed();if let Some(output)=output{wallet.close_owned(output);}wallet}
fn at_semantic(job:&mut funding::Funded<PathBooleanJob>,target:u64){for _ in 0..job.turn_bound(){if job.work>=target{return;}step(job,1).unwrap();}panic!("Finite path semantic checkpoint exhausted");}
fn refusal(job:&mut funding::Funded<PathBooleanJob>,items:usize)->BooleanError{for _ in 0..job.turn_bound(){if let Err(error)=step(job,items){return error;}}panic!("Expected retained path refusal was not reached");}
fn area(segments:&[PathSegment])->f64{let(mut origin,mut previous,mut sum)=([0.0;2],[0.0;2],0.0);for s in segments{match s{PathSegment::Move{to}=>{origin=*to;previous=*to;},PathSegment::Line{to}=>{sum+=((previous[0]-origin[0])*(to[1]-origin[1])-(previous[1]-origin[1])*(to[0]-origin[0]))/2.0;previous=*to;},PathSegment::Close=>{},_=>panic!("Unexpected unresolved curve")}}sum}
#[test]
fn neutral_curves_and_world_transforms_have_stable_grant_outputs(){for row in rows(){let source=input(&row);let mut previous=None;for grant in [1,7,4096]{let(result,p)=finish(source.clone(),grant);assert_eq!(result.iter().filter(|s|matches!(s,PathSegment::Move{..})).count(),row["contours"].as_u64().unwrap()as usize,"{}",row["id"]);if let Some(expected)=row["area"].as_f64(){assert!((area(&result)-expected).abs()<1e-8);}if let Some(before)=previous{assert_eq!(before,*result);}previous=Some(result.to_vec());assert_eq!(p.operands,source.operands.len());assert!(p.points<=source.max_edges);result.finish();}}}
#[test]
fn source_point_output_and_work_caps_fail_privately_and_stay_failed(){let source=input(&rows()[0]);let mut empty=source.clone();empty.operands.clear();let job=funded(empty);assert!(job.result().is_err());close(job);let mut zero=source.clone();zero.max_work=0;let job=funded(zero);assert!(job.result().is_err());close(job);for kind in 0..7{let mut value=source.clone();match kind{0=>value.max_edges=4,1=>value.max_work=2,2=>value.max_segments=2,3=>value.operands[0].transform[0]=f64::NAN,4=>value.operands[0].segments[0]=PathSegment::Move{to:[f64::NAN,0.0]},5=>value.operands[0].tolerance=0.0,_=>{value=input(&rows()[1]);value.max_edges=16;}}let mut job=funded(value);let error=refusal(&mut job,10000000);assert_eq!(step(&mut job,1).unwrap_err(),error);assert_eq!(job.last_turn_work(),0);assert_eq!(job.result().unwrap_err(),error);close(job);}let mut job=funded(source);assert!(step(&mut job,0).is_err());close(job);}
#[test]
fn cancellation_covers_every_path_stage_and_owned_results_survive(){let source=input(&rows()[1]);let mut probe=funded(source.clone());let mut seen=BTreeSet::new();let mut done=false;for _ in 0..probe.turn_bound(){let p=step(&mut probe,1).unwrap();if seen.insert(p.phase.as_str()){let mut job=funded(source.clone());at_semantic(&mut job,p.work);assert_eq!(job.phase,p.phase);job.cancel();assert_eq!(step(&mut job,1).unwrap_err(),BooleanError::Cancelled);assert_eq!(job.result().unwrap_err(),BooleanError::Cancelled);close(job);}if p.done{done=true;break;}}assert!(done);close(probe);assert_eq!(seen,BTreeSet::from(["admitting","flattening","transforming","boolean","complete"]));let mut job=funded(source);let mut done=false;for _ in 0..job.turn_bound(){if step(&mut job,10000000).unwrap().done{done=true;break;}}assert!(done);let published=job.result().unwrap().to_vec();job.cancel();assert!(!published.is_empty());let mut wallet=close(job);wallet.close_owned(published);}
#[test]
fn exact_caps_and_progress_fields_match_the_neutral_contract(){let source=input(&rows()[0]);let(expected,p)=finish(source.clone(),1);let b=p.boolean.unwrap();let mut exact=source;exact.max_edges=p.source_segments.max(p.points);exact.max_parameters=b.parameters;exact.max_atomic_edges=b.atomic_edges;exact.max_segments=b.segments;exact.max_work=p.work;let(actual,_)=finish(exact,7);assert_eq!(*actual,*expected);actual.finish();expected.finish();let value=json!({"phase":p.phase.as_str(),"operands":p.operands,"sourceSegments":p.source_segments,"points":p.points,"work":p.work,"flatten":p.flatten.map(|p|json!({"phase":match p.phase{semio_framework_2d_path_flatten::PathFlattenPhase::Preparing=>"preparing",semio_framework_2d_path_flatten::PathFlattenPhase::Subdividing=>"subdividing",semio_framework_2d_path_flatten::PathFlattenPhase::Complete=>"complete"},"completed":p.completed,"total":p.total,"points":p.points,"work":p.work,"done":p.done})),"boolean":b.work,"done":p.done});assert_eq!(value.as_object().unwrap().len(),8);}
#[test]
fn path_boolean_retirement_composes_child_owners_and_keeps_completed_output(){let fixtures:Value=serde_json::from_str(include_str!("🧫️fixtures/🧹️retirement/🔣️.json")).unwrap();let source_row=rows().into_iter().find(|r|r["id"]==fixtures["source"]).unwrap();for row in fixtures["cases"].as_array().unwrap(){for grant in [1,7,4096]{let mut source=input(&source_row);if let Some(n)=row["maxWork"].as_u64(){source.max_work=n;}if let Some(n)=row["maxSegments"].as_u64(){source.max_segments=n as usize;}let mut job=funded(source);let phase=row["phase"].as_str().unwrap();if phase=="failure"{refusal(&mut job,100000);if row["maxWork"].is_number(){assert!(job.current.is_some());}}else if phase!="fresh"{if phase!="cancelled"{let mut reached=false;for _ in 0..100000{let p=step(&mut job,1).unwrap();if match phase{"flattenClosing"=>job.flat_retirement.is_some(),"booleanClosing"=>job.boolean_retirement.is_some(),_=>p.phase.as_str()==phase}{reached=true;break;}}assert!(reached);}let target=job.work+row["offset"].as_u64().unwrap();at_semantic(&mut job,target);}if phase=="cancelled"{job.cancel();}let ptr=if job.phase==PathBooleanPhase::Complete&&!job.cancelled&&job.failure.is_none(){Some(job.result().unwrap().as_ptr())}else{None};let(mut retired,output)=job.retire_with(PathBooleanJob::into_retirement);if let Some(ptr)=ptr{assert_eq!(output.as_ref().unwrap().as_ptr(),ptr);let(expected,_)=finish(input(&source_row),4096);assert_eq!(output.as_ref().unwrap(),&*expected);expected.finish();}else{assert!(output.is_none());}let turns=drain(&mut retired,grant);assert!(turns>0);assert!(retired.terminal_is_empty());assert!(retired.owner.original().is_none());assert_eq!(drain(&mut retired,grant),0);let mut wallet=retired.finish_closed();if let Some(output)=output{wallet.close_owned(output);}}}}
